// Executado por item. A chave da API nunca entra nos dados deste node.
const chatId = String($json.chatId ?? '');
if (!/^-?\d+$/.test(chatId)) return null;
const originalQueue = String($json.queue ?? '');
const NOT_FOUND = '\u274c Cidade n\u00e3o encontrada. Use o formato Cidade,UF,BR (ex.: S\u00e3o Paulo,SP,BR).';
const base = { chatId, inputQueue: originalQueue, valid: false, ok: false, message: NOT_FOUND };

if (/^\/(start|help|ajuda)(@[a-z0-9_]+)?(?:\s.*)?$/i.test(originalQueue)) {
  return { json: { ...base, errorType: 'help', message: 'Ol\u00e1! Envie Cidade,UF,BR para consultar a temperatura. Ex.: S\u00e3o Paulo,SP,BR. Tamb\u00e9m aceito Cidade,UF.' } };
}

const parts = originalQueue.split(',').map(part => part.trim());
const city = (parts[0] ?? '').replace(/[\u2018\u2019]/g, "'");
const uf = (parts[1] ?? '').toUpperCase();
const country = (parts[2] ?? 'br').toLowerCase();
const states = new Set('AC AL AP AM BA CE DF ES GO MA MT MS MG PA PB PR PE PI RJ RN RS RO RR SC SP SE TO'.split(' '));
const validCity = city.length >= 2 && city.length <= 100 && /^[a-z0-9][a-z0-9 .'-]*$/.test(city) && /[a-z]/.test(city);
if ((parts.length !== 2 && parts.length !== 3) || !validCity || !states.has(uf) || country !== 'br') {
  return { json: { ...base, errorType: 'invalid_input' } };
}

// A API so documenta filtro por state code para os EUA. A UF brasileira
// e validada no resultado do Geocoding, nunca ignorada silenciosamente.
const cacheSlug = city.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase()
  .replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
return { json: { chatId, inputQueue: originalQueue, city, uf, country: 'BR',
                 queue: `${city},br`, cacheKey: `weather:br:${uf.toLowerCase()}:${cacheSlug}`, valid: true, ok: false } };

const base = $('Preparar consulta').item.json;
let raw = $json.value ?? $json.data ?? null;
let cached = null;
if (typeof raw === 'string' && raw.trim()) {
  try { cached = JSON.parse(raw); } catch {}
} else if (raw && typeof raw === 'object') cached = raw;
const valid = cached && cached.ok === true && Number.isFinite(Number(cached.temperature)) &&
  typeof cached.cityName === 'string' && cached.cityName && cached.uf === base.uf;
if (!valid) return { json: { ...base, cacheHit: false } };
const temperature = Math.round(Number(cached.temperature));
const cityName = cached.cityName.trim();
const message = `🌤️ A temperatura em ${cityName} (${base.uf}) é de ${temperature}°C.`;
const escapeHtml = v => String(v).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
return { json: { chatId: base.chatId, queue: base.queue, cacheKey: base.cacheKey, cityName, uf: base.uf,
  statusCode: 200, ok: true, retryCoordinates: false, temperature, cacheHit: true,
  message, telegramText: escapeHtml(message) } };

const input = $('Preparar consulta').item.json;
const NOT_FOUND = '\u274c Cidade n\u00e3o encontrada. Use o formato Cidade,UF,BR (ex.: S\u00e3o Paulo,SP,BR).';
const UNAVAILABLE = '\u26a0\ufe0f N\u00e3o consegui consultar a temperatura agora. Tente novamente em instantes.';
const rawStatus = Number($json.statusCode ?? 0);
const statusCode = Number.isInteger(rawStatus) ? rawStatus : 0;
const fail = (errorType, message = NOT_FOUND) => ({ json: {
  ...input, found: false, ok: false, statusCode, errorType, message
} });

// Nao repassar error/headers/body brutos: podem conter detalhes da requisicao.
if ($json.error || statusCode === 0 || [401, 403, 429].includes(statusCode) || statusCode >= 500) {
  return fail('geocoding_unavailable', UNAVAILABLE);
}
if (statusCode < 200 || statusCode >= 300) return fail('geocoding_http_error');
let body = $json.body;
if (typeof body === 'string') {
  try { body = JSON.parse(body); } catch { return fail('invalid_geocoding_json'); }
}
if (!Array.isArray(body)) return fail('invalid_geocoding_body');

const normalize = value => String(value ?? '').normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '').toLowerCase().trim()
  .replace(/[\u2018\u2019]/g, "'").replace(/\s+/g, ' ');
const stateNames = {
  AC: 'acre', AL: 'alagoas', AP: 'amapa', AM: 'amazonas', BA: 'bahia',
  CE: 'ceara', DF: 'distrito federal', ES: 'espirito santo', GO: 'goias',
  MA: 'maranhao', MT: 'mato grosso', MS: 'mato grosso do sul', MG: 'minas gerais',
  PA: 'para', PB: 'paraiba', PR: 'parana', PE: 'pernambuco', PI: 'piaui',
  RJ: 'rio de janeiro', RN: 'rio grande do norte', RS: 'rio grande do sul',
  RO: 'rondonia', RR: 'roraima', SC: 'santa catarina', SP: 'sao paulo',
  SE: 'sergipe', TO: 'tocantins'
};
const stateMatches = value => {
  const state = normalize(value).replace(/^(state of |estado (?:de|do|da) )/, '').replace(/ state$/, '');
  return state === input.uf.toLowerCase() || state === `br-${input.uf.toLowerCase()}` ||
         state === stateNames[input.uf] || (input.uf === 'DF' && state === 'federal district');
};
const validCoord = place => typeof place.lat === 'number' && Number.isFinite(place.lat) &&
  typeof place.lon === 'number' && Number.isFinite(place.lon) &&
  Math.abs(place.lat) <= 90 && Math.abs(place.lon) <= 180;
const matches = body.filter(place => {
  if (!place || typeof place !== 'object' || Array.isArray(place)) return false;
  const names = [place.name, ...Object.values(place.local_names ?? {})];
  return place.country === 'BR' && stateMatches(place.state) && validCoord(place) &&
    names.some(name => typeof name === 'string' && normalize(name) === input.city);
});
const unique = matches.filter((place, index) => !matches.slice(0, index).some(previous =>
  Math.abs(place.lat - previous.lat) < 0.0001 && Math.abs(place.lon - previous.lon) < 0.0001));
if (unique.length === 0) return fail('city_or_state_not_found');
if (unique.length > 1) return fail('ambiguous_city');
const place = unique[0];
const cityName = [place.local_names?.pt_br, place.local_names?.pt, place.name]
  .find(name => typeof name === 'string' && name.trim().length > 0);
if (!cityName) return fail('missing_city_name');
return { json: { ...input, found: true, ok: false, cityName: cityName.trim(),
                 latitude: place.lat, longitude: place.lon } };

const place = $('Selecionar cidade e UF').item.json;
const NOT_FOUND = '\u274c Cidade n\u00e3o encontrada. Use o formato Cidade,UF,BR (ex.: S\u00e3o Paulo,SP,BR).';
const UNAVAILABLE = '\u26a0\ufe0f N\u00e3o consegui consultar a temperatura agora. Tente novamente em instantes.';
const rawStatus = Number($json.statusCode ?? 0);
const statusCode = Number.isInteger(rawStatus) ? rawStatus : 0;
const fail = (errorType, message = NOT_FOUND, retryCoordinates = false) => ({ json: {
  ...place, ok: false, retryCoordinates, statusCode, errorType, message
} });
if ($json.error || statusCode === 0 || [401, 403, 429].includes(statusCode) || statusCode >= 500) {
  return fail('weather_unavailable', UNAVAILABLE);
}
let body = $json.body;
if (typeof body === 'string') {
  try { body = JSON.parse(body); } catch { return fail('invalid_weather_json'); }
}
const code = Number(body?.cod ?? 0);
if ([401, 403, 429].includes(code) || code >= 500) return fail('weather_api_unavailable', UNAVAILABLE);
const validBody = statusCode >= 200 && statusCode < 300 && code === 200 &&
  body && typeof body === 'object' && !Array.isArray(body) &&
  typeof body.main?.temp === 'number' && Number.isFinite(body.main.temp) &&
  typeof body.name === 'string' && body.name.trim().length > 0;
const sameLocation = body?.sys?.country === 'BR' &&
  typeof body.coord?.lat === 'number' && Number.isFinite(body.coord.lat) &&
  typeof body.coord?.lon === 'number' && Number.isFinite(body.coord.lon) &&
  Math.abs(body.coord.lat - place.latitude) <= 0.01 &&
  Math.abs(body.coord.lon - place.longitude) <= 0.01;

// Preserva a chamada q=queue pedida pelo exercicio, mas nao aceita clima
// de uma cidade homonima. A alternativa por coordenadas so roda quando precisa.
if (statusCode === 404 || code === 404) return fail('retry_by_coordinates', NOT_FOUND, true);
if (!validBody) return fail('invalid_weather_body');
if (!sameLocation) return fail('retry_by_coordinates', NOT_FOUND, true);

// Math.round nao transforma null, strings ou campos ausentes em temperatura.
const temperature = Math.round(body.main.temp);
const escapeHtml = value => String(value).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const message = `\ud83c\udf24\ufe0f A temperatura em ${place.cityName} (${place.uf}) \u00e9 de ${temperature}\u00b0C.`;
return { json: { chatId: place.chatId, queue: place.queue, cacheKey: place.cacheKey, cityName: place.cityName, uf: place.uf,
  statusCode, ok: true, retryCoordinates: false, temperature,
  message, telegramText: escapeHtml(message) } };

const place = $('Selecionar cidade e UF').item.json;
const NOT_FOUND = '\u274c Cidade n\u00e3o encontrada. Use o formato Cidade,UF,BR (ex.: S\u00e3o Paulo,SP,BR).';
const UNAVAILABLE = '\u26a0\ufe0f N\u00e3o consegui consultar a temperatura agora. Tente novamente em instantes.';
const rawStatus = Number($json.statusCode ?? 0);
const statusCode = Number.isInteger(rawStatus) ? rawStatus : 0;
const fail = (errorType, message = NOT_FOUND, retryCoordinates = false) => ({ json: {
  ...place, ok: false, retryCoordinates, statusCode, errorType, message
} });
if ($json.error || statusCode === 0 || [401, 403, 429].includes(statusCode) || statusCode >= 500) {
  return fail('weather_unavailable', UNAVAILABLE);
}
let body = $json.body;
if (typeof body === 'string') {
  try { body = JSON.parse(body); } catch { return fail('invalid_weather_json'); }
}
const code = Number(body?.cod ?? 0);
if ([401, 403, 429].includes(code) || code >= 500) return fail('weather_api_unavailable', UNAVAILABLE);
const validBody = statusCode >= 200 && statusCode < 300 && code === 200 &&
  body && typeof body === 'object' && !Array.isArray(body) &&
  typeof body.main?.temp === 'number' && Number.isFinite(body.main.temp) &&
  typeof body.name === 'string' && body.name.trim().length > 0;
const sameLocation = body?.sys?.country === 'BR' &&
  typeof body.coord?.lat === 'number' && Number.isFinite(body.coord.lat) &&
  typeof body.coord?.lon === 'number' && Number.isFinite(body.coord.lon) &&
  Math.abs(body.coord.lat - place.latitude) <= 0.01 &&
  Math.abs(body.coord.lon - place.longitude) <= 0.01;

if (!validBody || !sameLocation) return fail('invalid_coordinate_weather');

// Math.round nao transforma null, strings ou campos ausentes em temperatura.
const temperature = Math.round(body.main.temp);
const escapeHtml = value => String(value).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const message = `\ud83c\udf24\ufe0f A temperatura em ${place.cityName} (${place.uf}) \u00e9 de ${temperature}\u00b0C.`;
return { json: { chatId: place.chatId, queue: place.queue, cacheKey: place.cacheKey, cityName: place.cityName, uf: place.uf,
  statusCode, ok: true, retryCoordinates: false, temperature,
  message, telegramText: escapeHtml(message) } };

const source = $json;
if (source.ok !== true || !Number.isFinite(Number(source.temperature))) return { json: source };
const deterministicMessage = source.message || `🌤️ A temperatura em ${source.cityName} (${source.uf}) é de ${Math.round(Number(source.temperature))}°C.`;
return { json: { ...source, deterministicMessage,
  geminiPrompt: `Reescreva de forma curta, clara e amigável a mensagem de temperatura abaixo. Não altere cidade, UF ou temperatura. Não invente previsão, sensação térmica ou qualquer outro dado. Retorne SOMENTE JSON válido no formato {\"message\":\"texto\",\"ok\":true}. Mensagem base: ${deterministicMessage}` } };

const base = $('Preparar mensagem para IA').item.json;
const fallback = base.deterministicMessage || base.message;
const walk = obj => {
  if (!obj) return null;
  if (typeof obj === 'string') return obj;
  if (Array.isArray(obj)) { for (const v of obj) { const r = walk(v); if (r) return r; } return null; }
  if (typeof obj === 'object') {
    if (typeof obj.message === 'string') return JSON.stringify({ message: obj.message, ok: obj.ok ?? true });
    for (const k of ['text','content','output','response','parts','candidates']) { if (k in obj) { const r=walk(obj[k]); if (r) return r; } }
  }
  return null;
};
let candidate = walk($json);
let parsed = null;
if (candidate) {
  try { parsed = JSON.parse(candidate.replace(/^```json\s*/i,'').replace(/```$/,'').trim()); } catch {}
}
const sameTemp = parsed?.message && String(parsed.message).includes(`${Math.round(Number(base.temperature))}°C`);
const sameUf = parsed?.message && String(parsed.message).toUpperCase().includes(`(${String(base.uf).toUpperCase()})`);
const message = parsed?.ok === true && sameTemp && sameUf && String(parsed.message).length <= 240 ? String(parsed.message).trim() : fallback;
const escapeHtml = v => String(v).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
return { json: { ...base, geminiUsed: message !== fallback, message, telegramText: escapeHtml(message) } };
